#!/usr/bin/env python3
# Audit k_41, k_43: the index of the A-submodule generated by the n rows of an n x n matrix C over A = Z[x]/(Phi_p).
# Rewritten after reading audit/k37/nmdet.py (same mathematics; other auxiliary primes; the bound is the smaller of the row and the
# column Hadamard bounds; a second evaluation with FLINT for cross-checking single residues).
# A matrix is a list of n rows, a row is a list of n entries, an entry is a list of p-1 integers (coefficients of 1, x, ..., x^(p-2)).
#   zmatrix(C): the (p-1)n x (p-1)n integer matrix whose rows are the coefficient vectors of x^j * (row i), j = 0..p-2.  Its rows are a
#       Z-basis of the A-span of the rows of C when det != 0; it is the matrix of the Z-linear map v -> v C of A^n in the Z-basis x^j e_i,
#       so det zmatrix(C) = Nm(det C) (norm of Q(zeta_p)/Q) and |det| is the index.
#   nm_crt(C): Nm(det C) by the Chinese remainder theorem: modulo primes l = 1 mod p (increasing from 2^62 + 2^61; relations/span.py uses
#       primes decreasing from 2^62, audit/k37 primes increasing from 2^61), Nm(det C) = prod_{e=1}^{p-1} det C(w^e) mod l, w of order p mod l
#       (Phi_p splits into x - w^e modulo l).  Determinants by PARI (matdet of matrices of Mod).  Stop when the product of the l exceeds
#       2 * bound, bound >= |det zmatrix(C)| (Hadamard), and take the symmetric residue.
import math
import cypari2
from flint import nmod_mat
pari=cypari2.Pari(); pari.allocatemem(2*10**9,silent=True)
def need(c,msg):
    if not c: raise SystemExit("AUDIT FAILED: "+str(msg))
def mulx(e,p):                                        # x * e in A; e has length p-1;  x^(p-1) = -(1 + x + ... + x^(p-2))
    top=e[-1]; return [-top]+[e[k-1]-top for k in range(1,p-1)]
def zmatrix(C,p):
    out=[]
    for row in C:
        cur=[list(e) for e in row]
        for j in range(p-1):
            out.append([c for e in cur for c in e]); cur=[mulx(e,p) for e in cur]
    return out
def hadamard_bound(Z):                                # integer B with |det Z| <= B: min of the row bound and the column bound
    sr=1
    for r in Z: sr*=sum(c*c for c in r)
    sc=1
    for j in range(len(Z)): sc*=sum(Z[i][j]*Z[i][j] for i in range(len(Z)))
    return math.isqrt(min(sr,sc))+1
_aux={}
def next_aux(p,k):
    if p not in _aux: _aux[p]=[((2**62+2**61)//p)*p+1,[]]
    st=_aux[p]
    while len(st[1])<=k:
        l=st[0]+p
        while not pari.isprime(l): l+=p
        st[0]=l; w=1
        for a in range(2,1000):
            w=pow(a,(l-1)//p,l)
            if w!=1: break
        need(l%p==1 and l<2**63 and w!=1 and pow(w,p,l)==1,"root of unity"); st[1].append((l,w))
    return st[1][k]
_nmdetmod=pari("(E,n,p,l,w)->my(V=matrix(p-1,p-1,d,e,Mod(w,l)^((d-1)*e)),EV=E*V,v=Mod(1,l));for(e=1,p-1,v*=matdet(matrix(n,n,i,j,EV[(i-1)*n+j,e])));lift(v)")
def nm_mod_flint(C,p,l,w):                            # the same residue with FLINT (python loops for the evaluation)
    n=len(C); v=1
    for e in range(1,p):
        pw=[pow(w,d*e,l) for d in range(p-1)]
        v=v*int(nmod_mat(n,n,[sum(c*x for c,x in zip(ent,pw))%l for row in C for ent in row],l).det())%l
    return v
def nm_crt(C,p,bound=None,flint_checks=0):
    n=len(C)
    if bound is None: bound=hadamard_bound(zmatrix(C,p))
    E=pari.matrix(n*n,p-1,[c for row in C for ent in row for c in ent])
    mod=1; res=0; k=0
    while mod<=2*bound:
        l,w=next_aux(p,k); k+=1
        v=int(_nmdetmod(E,n,p,l,w))
        if k<=flint_checks: need(v==nm_mod_flint(C,p,l,w),"PARI and FLINT residues differ")
        res=res+mod*((v-res)*pow(mod,-1,l)%l); mod*=l
    if res>mod//2: res-=mod
    return res,k
def trace_form(row,p): return sum(p*sum(c*c for c in e)-sum(e)**2 for e in row)
if __name__=="__main__":                              # self-test: nm_crt against the exact determinant of zmatrix (PARI and FLINT)
    import random
    from flint import fmpz_mat
    random.seed(20261125); cnt=0
    for p,n in ((3,2),(5,3),(7,4),(41,2),(41,4),(43,3),(43,4)):
        for _ in range(4):
            C=[[[random.randint(-3,3) for _ in range(p-1)] for _ in range(n)] for _ in range(n)]
            Z=zmatrix(C,p); flat=[c for r in Z for c in r]; dz=int(pari.matrix(len(Z),len(Z),flat).matdet()); dz2=int(fmpz_mat(len(Z),len(Z),flat).det())
            nm,k=nm_crt(C,p,flint_checks=3)
            need(dz==dz2 and dz==nm,"self-test p=%d n=%d: %d %d %d"%(p,n,dz,dz2,nm)); cnt+=1
    # a singular matrix and a matrix with a known index: diag(1 - x, 1) has index Nm(1 - x) = p
    for p in (41,43):
        one=[1]+[0]*(p-2); zero=[0]*(p-1); omx=[1,-1]+[0]*(p-3)
        need(nm_crt([[omx,zero],[zero,one]],p)[0]==p,"Nm(1-x)"); need(nm_crt([[omx,omx],[omx,omx]],p)[0]==0,"singular")
    print("nmdet2 self-test passed: det zmatrix(C) = Nm(det C) (with sign) on %d random matrices; Nm(1 - x) = p; singular -> 0"%cnt)
